package com.yilu.yinling.user.controller;
import com.yilu.yinling.common.response.Result; import com.yilu.yinling.user.dto.AuthDto; import com.yilu.yinling.user.service.UserService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/users") public class UserController { private final UserService service; public UserController(UserService s){service=s;} private Long id(Authentication a){return (Long)a.getDetails();} @GetMapping("/me") public Result<AuthDto.UserView> me(Authentication a){return Result.ok(service.current(id(a)));} @PutMapping("/me") public Result<AuthDto.UserView> update(Authentication a,@RequestBody AuthDto.UserView r){return Result.ok(service.update(id(a),r));} }
